//! Runs every golden case of `testdata/` (generated by `mise run oracle` with the LiteRT
//! reference kernels) and compares nanonn's outputs with the expected ones.

use nanonn::{Encoding, Graph, Target};
mod common;

use common::{Aligned, repo_root};
use nanonn::core::allocator_api2::alloc::Global;
use std::path::PathBuf;

struct Case {
    dir: PathBuf,
    json: serde_json::Value,
}

fn cases() -> Vec<Case> {
    fn walk(dir: &std::path::Path, out: &mut Vec<Case>) {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(&path, out);
            } else if path.file_name().is_some_and(|n| n == "case.json") {
                let text = std::fs::read_to_string(&path).unwrap();
                let json = serde_json::from_str(&text)
                    .unwrap_or_else(|e| panic!("{}: {e}", path.display()));
                out.push(Case {
                    dir: dir.to_path_buf(),
                    json,
                });
            }
        }
    }
    let mut out = Vec::new();
    walk(&repo_root().join("testdata"), &mut out);
    out.sort_by(|a, b| a.dir.cmp(&b.dir));
    out
}

fn dtype_size(dtype: &str) -> usize {
    match dtype {
        "int8" | "uint8" | "bool" => 1,
        "int16" => 2,
        "int32" | "float32" => 4,
        "int64" => 8,
        other => panic!("unknown dtype {other}"),
    }
}

/// Largest difference between `actual` and `expected`, in elements of `dtype`.
fn max_diff(dtype: &str, actual: &[u8], expected: &[u8]) -> f64 {
    let size = dtype_size(dtype);
    actual
        .chunks_exact(size)
        .zip(expected.chunks_exact(size))
        .map(|(a, e)| match dtype {
            "int8" => (a[0] as i8 as f64 - e[0] as i8 as f64).abs(),
            "uint8" | "bool" => (a[0] as f64 - e[0] as f64).abs(),
            "int16" => (i16::from_le_bytes([a[0], a[1]]) as f64
                - i16::from_le_bytes([e[0], e[1]]) as f64)
                .abs(),
            "int32" => (i32::from_le_bytes(a.try_into().unwrap()) as f64
                - i32::from_le_bytes(e.try_into().unwrap()) as f64)
                .abs(),
            "float32" => {
                let (a, e) = (
                    f32::from_le_bytes(a.try_into().unwrap()),
                    f32::from_le_bytes(e.try_into().unwrap()),
                );
                ((a - e).abs() / e.abs().max(1.0)) as f64
            }
            _ => f64::INFINITY,
        })
        .fold(0.0, f64::max)
}

fn run(case: &Case) -> Result<(), String> {
    let model = Aligned::read(&repo_root().join(case.json["model"].as_str().unwrap()));
    let graph = Graph::load_in(&[model.bytes()], Encoding::Autodetect, Target::Auto, Global)
        .map_err(|e| format!("load: {e}"))?;
    let mut ctx = graph
        .init_execution_context_in(Global)
        .map_err(|e| format!("context: {e}"))?;
    let tolerance = case.json["tolerance"].as_f64().unwrap_or(0.0);

    for (i, _) in case.json["inputs"].as_array().unwrap().iter().enumerate() {
        let data = std::fs::read(case.dir.join(format!("input_{i}.bin"))).unwrap();
        ctx.set_input(i, &data)
            .map_err(|e| format!("input {i}: {e}"))?;
    }
    ctx.compute().map_err(|e| format!("compute: {e}"))?;
    for (i, spec) in case.json["outputs"].as_array().unwrap().iter().enumerate() {
        let expected = std::fs::read(case.dir.join(format!("output_{i}.bin"))).unwrap();
        let actual = ctx.output(i).map_err(|e| format!("output {i}: {e}"))?;
        if actual.bytes().len() != expected.len() {
            return Err(format!(
                "output {i}: {} bytes, expected {}",
                actual.bytes().len(),
                expected.len()
            ));
        }
        let diff = max_diff(spec["dtype"].as_str().unwrap(), actual.bytes(), &expected);
        if diff > tolerance {
            return Err(format!(
                "output {i}: max diff {diff} > tolerance {tolerance}"
            ));
        }
    }
    Ok(())
}

/// Cases that are expected to fail for now, with the reason. A listed case that passes fails the
/// test too, so the list never goes stale.
const PENDING: &[(&str, &str)] = &[
    // LiteRT's reference FULLY_CONNECTED requantizes in floating point (`round(acc * scale)`),
    // while TFLite Micro and CMSIS-NN use fixed point: deep FC stacks drift by one unit or two.
    (
        "mlperf-tiny/golden/ad01_int8/sample_0",
        "LiteRT float requantization in FULLY_CONNECTED",
    ),
    (
        "mlperf-tiny/golden/ad01_int8/sample_1",
        "LiteRT float requantization in FULLY_CONNECTED",
    ),
    (
        "mlperf-tiny/golden/ad01_int8/sample_2",
        "LiteRT float requantization in FULLY_CONNECTED",
    ),
    ("ops/fully_connected_per_channel_int16", "int16 kernels"),
    ("ops/softmax_2d_int16", "int16 kernels"),
];

#[test]
fn golden_cases() {
    let cases = cases();
    let root = repo_root().join("testdata");
    let mut failures = Vec::new();
    let mut pending = 0;
    for case in &cases {
        let name = case
            .dir
            .strip_prefix(&root)
            .unwrap_or(&case.dir)
            .display()
            .to_string();
        let reason = PENDING.iter().find(|(n, _)| *n == name).map(|(_, r)| *r);
        match (run(case), reason) {
            (Ok(()), None) => println!("ok       {name}"),
            (Err(e), Some(reason)) => {
                pending += 1;
                println!("pending  {name}: {e} ({reason})");
            }
            (Ok(()), Some(_)) => {
                println!("FIXED    {name}: remove it from PENDING");
                failures.push(name);
            }
            (Err(e), None) => {
                println!("FAIL     {name}: {e}");
                failures.push(name);
            }
        }
    }
    println!(
        "{} cases, {pending} pending, {} failures",
        cases.len(),
        failures.len()
    );
    assert!(cases.len() > 100, "test data not found");
    assert!(failures.is_empty(), "failing cases: {failures:#?}");
}
